#define beat (iTime * 4.)

const float E = 0.001;
const float PI = 3.14159265;

float diameter = 1.0;
float rotOffset = 0.0;
float scorchedFactor = 1.0;

mat3 rotY(float r){return mat3(cos(r), 0., sin(r), 0., 1., 0., -sin(r), 0., cos(r));}
mat3 rotX(float r){return mat3(1., 0., 0., 0., cos(r), sin(r), 0., -sin(r), cos(r));}
mat3 rotZ(float r){return mat3(cos(r), sin(r), 0., -sin(r), cos(r), 0., 0., 0., 1.);}

vec2 sphereUV(vec3 intersectionPoint, float offset) {
    vec2 uv = vec2(
        atan(intersectionPoint.z, intersectionPoint.x) / (2.0 * PI) + 0.5 + offset,
        acos(intersectionPoint.y) / PI
    );
    return uv;
}

float sphere(vec3 p, float radius){
    return length(p) - radius;
}

float box(vec3 p, vec3 b){
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

vec2 scene_with_id(vec3 p) {
	vec3 q = p;
	q.y /= diameter;
	vec2 uvs = sphereUV(q, beat/64.000 + rotOffset + 0.000);
	vec4 tectonics = texture(iChannel1, mod(uvs, 1.));
	float dd = 0.0;
	float bolleke = sphere(p, diameter);
	if (bolleke < 0.1 && scorchedFactor > 0.1)
		bolleke = sphere(p, diameter - smoothstep(0.500, 1.000, tectonics.x) * 0.05 * scorchedFactor); // @tect

	float background = sphere(p, -100.0);

	float universe = min(bolleke, background);

    return vec2(universe, (bolleke < background ? 1.0 : 2.0));
}

float scene(vec3 p) {
    return scene_with_id(p).x;
}


vec3 normal(vec3 p) {
    return normalize(vec3(
        scene(vec3(p.x + E, p.y, p.z)) - scene(vec3(p.x - E, p.y, p.z)),
        scene(vec3(p.x, p.y + E, p.z)) - scene(vec3(p.x, p.y - E, p.z)),
        scene(vec3(p.x, p.y, p.z + E)) - scene(vec3(p.x, p.y, p.z - E))
    ));
}


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 uv2 = fragCoord/iResolution.xy;

    float aspect = iResolution.x / iResolution.y;

    vec3 col = vec3(0.000,0.369,0.722);

    uv -= 0.5;
    uv.y /= aspect;

    vec3 lightColor = vec3(0.985,0.946,0.628);

    vec3 ro = vec3(0.0, 0.0, -5.);
    vec3 rd = normalize(vec3(uv, 1.0));
    float dayNight = -beat / 8.0;
    vec3 ld = vec3(0.5, 0.5, -1.);
    float t = 0.0;
    float d = 0.0;
    float id = 0.0;
    vec4 c = vec4(0.000,0.067,1.000,1.);
    bool hit = false;
    for (int i = 0; i < 128; i++){
        vec3 p = ro + t * rd;

        p = rotX(0.5 ) * p;

        vec2 result = scene_with_id(p);
        d = result.x;
        id = result.y;
        if (abs(d) < E) {
            // hit
            hit = true;
            vec3 n = normal(p);
            float l = smoothstep(0.0, 1.0, dot(n, ld));

            p.y /= diameter;

            vec2 uvs = sphereUV(p, beat/64. + rotOffset);
            vec2 uvsClouds = sphereUV(p, 0.);


            if (id == 1.0) {
            	c = texture(iChannel0, mod(uvs, 1.)) * l;

            	vec4 tectonics = texture(iChannel1, mod(uvs, 1.));

            	vec3 scorched = c.rgb;

            	vec3 scorchedColor = vec3(0.984,0.486,0.075);

            	scorched.rgb = mix(c.rgb, scorchedColor, l * smoothstep(0.669, 0.875, tectonics.r));

            	c.rgb = mix(c.rgb, scorched, scorchedFactor);
            }


            break;
        }
        t += d * 0.8;
    }

    // Output to screen
    fragColor = c;
}
